update public.lessons set content='{"intro": "Nesta aula vai aprender «Terreno urbanizável: expressão comercial vs. classificação do solo» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Terreno urbanizável: expressão comercial vs. classificação do solo», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Terreno urbanizável: expressão comercial vs. classificação do solo» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-regulamentar/15-2015-70055492', verified_at=date '2026-08-20' where id=194;
