update public.lessons set content='{"intro": "Nesta aula vai aprender «Como ler o PDM sem ser urbanista» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "PDM — PDM significa Plano Diretor Municipal: instrumento territorial municipal que contém regras de organização e uso do território. Deve ser lido através das plantas e do regulamento aplicável."}, {"title": "O que é o PDM", "body": "PDM significa Plano Diretor Municipal: instrumento territorial municipal que contém regras de organização e uso do território. Deve ser lido através das plantas e do regulamento aplicável."}, {"title": "Planta de ordenamento", "body": "Localiza e enquadra o solo/categoria segundo o plano."}, {"title": "Planta de condicionantes", "body": "Mostra condicionamentos/servidões relevantes que se sobrepõem ao ordenamento."}, {"title": "Regulamento", "body": "Contém regras, usos e parâmetros. Uma cor no mapa não basta: é preciso ler a norma correspondente."}, {"title": "Solo urbano/rústico", "body": "São categorias de classificação territorial; nenhuma delas, isoladamente, responde a toda a edificabilidade."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Como ler o PDM sem ser urbanista», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Como ler o PDM sem ser urbanista» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/2015-105297982', verified_at=date '2026-08-20' where id=200;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Classificação, qualificação e categoria de espaço» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "PDM — PDM significa Plano Diretor Municipal: instrumento territorial municipal que contém regras de organização e uso do território. Deve ser lido através das plantas e do regulamento aplicável."}, {"title": "O que é o PDM", "body": "PDM significa Plano Diretor Municipal: instrumento territorial municipal que contém regras de organização e uso do território. Deve ser lido através das plantas e do regulamento aplicável."}, {"title": "Planta de ordenamento", "body": "Localiza e enquadra o solo/categoria segundo o plano."}, {"title": "Planta de condicionantes", "body": "Mostra condicionamentos/servidões relevantes que se sobrepõem ao ordenamento."}, {"title": "Regulamento", "body": "Contém regras, usos e parâmetros. Uma cor no mapa não basta: é preciso ler a norma correspondente."}, {"title": "Solo urbano/rústico", "body": "São categorias de classificação territorial; nenhuma delas, isoladamente, responde a toda a edificabilidade."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Classificação, qualificação e categoria de espaço», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Classificação, qualificação e categoria de espaço» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-regulamentar/15-2015-70055492', verified_at=date '2026-08-20' where id=201;
