update public.lessons set content='{"intro": "Nesta aula vai aprender «Estratégias: vender, licenciar ou desenvolver» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Estratégias: vender, licenciar ou desenvolver», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Estratégias: vender, licenciar ou desenvolver» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-lei/108-2026-1128002421', verified_at=date '2026-08-20' where id=214;
update public.lessons set content='{"intro": "Nesta aula vai aprender «O que é o PIP e quando faz sentido» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "PIP — PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que é o PIP", "body": "PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que se pede", "body": "A pergunta submetida deve corresponder à operação que se quer esclarecer; um PIP só responde ao que foi efetivamente apreciado."}, {"title": "Como ler uma decisão", "body": "Identificar prédio, pedido, peças, decisão, condicionantes, entidades consultadas e efeitos/prazos aplicáveis."}, {"title": "O que não é", "body": "Não é sinónimo de licença de construção nem autorização para qualquer projeto diferente do apreciado."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «O que é o PIP e quando faz sentido», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «O que é o PIP e quando faz sentido» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-lei/108-2026-1128002421', verified_at=date '2026-08-20' where id=215;
update public.lessons set content='{"intro": "Nesta aula vai aprender «PIP em 2026: novos modelos e elementos» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "PIP — PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que é o PIP", "body": "PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que se pede", "body": "A pergunta submetida deve corresponder à operação que se quer esclarecer; um PIP só responde ao que foi efetivamente apreciado."}, {"title": "Como ler uma decisão", "body": "Identificar prédio, pedido, peças, decisão, condicionantes, entidades consultadas e efeitos/prazos aplicáveis."}, {"title": "O que não é", "body": "Não é sinónimo de licença de construção nem autorização para qualquer projeto diferente do apreciado."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «PIP em 2026: novos modelos e elementos», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «PIP em 2026: novos modelos e elementos» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/portaria/320-2026-1153698591', verified_at=date '2026-08-20' where id=216;
update public.lessons set content='{"intro": "Nesta aula vai aprender «O que um PIP favorável não significa» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "PIP — PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que é o PIP", "body": "PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que se pede", "body": "A pergunta submetida deve corresponder à operação que se quer esclarecer; um PIP só responde ao que foi efetivamente apreciado."}, {"title": "Como ler uma decisão", "body": "Identificar prédio, pedido, peças, decisão, condicionantes, entidades consultadas e efeitos/prazos aplicáveis."}, {"title": "O que não é", "body": "Não é sinónimo de licença de construção nem autorização para qualquer projeto diferente do apreciado."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «O que um PIP favorável não significa», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «O que um PIP favorável não significa» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-lei/108-2026-1128002421', verified_at=date '2026-08-20' where id=217;
update public.lessons set content='{"intro": "Nesta aula vai aprender «As fases de um projeto imobiliário» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «As fases de um projeto imobiliário», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «As fases de um projeto imobiliário» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-lei/108-2026-1128002421', verified_at=date '2026-08-20' where id=218;
