update public.lessons set content='{"intro": "Nesta aula vai aprender «Caso: terreno urbano com índice aparentemente favorável» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Caso: terreno urbano com índice aparentemente favorável», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Caso: terreno urbano com índice aparentemente favorável» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-regulamentar/15-2015-70055492', verified_at=date '2026-08-20' where id=227;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Caso: terreno em REN alterada em 2026» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Caso: terreno em REN alterada em 2026», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Caso: terreno em REN alterada em 2026» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-lei/129-2026-1139897686', verified_at=date '2026-08-20' where id=228;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Caso: vendedor anuncia “projeto aprovado”» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Caso: vendedor anuncia “projeto aprovado”» deve ser entendido no contexto do módulo «Casos práticos». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Caso: vendedor anuncia “projeto aprovado”», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Caso: vendedor anuncia “projeto aprovado”» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/decreto-lei/108-2026-1128002421', verified_at=date '2026-08-20' where id=229;
commit;
select c.title,count(*) aulas,count(*) filter(where l.verified_at=date '2026-08-20') verificadas
from public.courses c join public.modules m on m.course_id=c.id join public.lessons l on l.module_id=m.id
where c.slug='terrenos' group by c.id,c.title;